  FROM creatures WHERE slug IN ('cactus-people', 'fennodi', 'keeper-of-the-desert', 'lyn-srial', 'mountain-giant', 'desert-sleeper', 'devil-unicorn', 'duckbilled-honker', 'giant-canyon-worms', 'great-dream-snake', 'great-plains-buffalo', 'grigleapers', 'gwylack', 'leatherwing', 'mammoth-brontodon', 'moss-back-scuttler', 'oborus-slitherer', 'ostrosaurus', 'panthera-tereon', 'psi-ponies', 'phantasm', 'rhino-buffalo', 'tiger-claw-raptor', 'tree-spiders', 'tri-tops', 'tyrannosaurus-rex', 'whisker-coyote', 'worm-wraith');
